package com.citacloud.springboot.contacloud.app.services;

import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.data.domain.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
import java.math.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.util.*;

@Service public class VentaGuardadaService {
 private static final int SCALE=4;private final VentaGuardadaRepository ventas;private final LineaVentaGuardadaRepository lineas;private final TerminalPosRepository terminales;private final CashRegisterRepository cajas;private final SucursalRepository sucursales;private final PosWarehouseResolver almacenes;private final ProductRepository productos;private final ClienteRepository clientes;private final InventoryMovementRepository existencias;private final AuditoriaService auditoria;private final DescuentoVentaService descuentos;private final RecargoVentaService recargos;private final JdbcTemplate jdbc;
 public VentaGuardadaService(VentaGuardadaRepository ventas,LineaVentaGuardadaRepository lineas,TerminalPosRepository terminales,CashRegisterRepository cajas,SucursalRepository sucursales,PosWarehouseResolver almacenes,ProductRepository productos,ClienteRepository clientes,InventoryMovementRepository existencias,AuditoriaService auditoria,DescuentoVentaService descuentos,RecargoVentaService recargos,JdbcTemplate jdbc){this.ventas=ventas;this.lineas=lineas;this.terminales=terminales;this.cajas=cajas;this.sucursales=sucursales;this.almacenes=almacenes;this.productos=productos;this.clientes=clientes;this.existencias=existencias;this.auditoria=auditoria;this.descuentos=descuentos;this.recargos=recargos;this.jdbc=jdbc;}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('ventas_guardadas.guardar')")
 public VentaGuardadaResultadoDto guardar(GuardarVentaInput input){if(input==null||input.lineas()==null||input.lineas().isEmpty())throw new ReglaNegocioException("No hay una venta para guardar.");if(input.lineas().size()>200)throw new ReglaNegocioException("La venta excede el máximo de 200 líneas.");Contexto ctx=contexto(input.token(),input.almacenId());var p=ctx.principal;VentaGuardada venta;Map<UUID,LineaVentaGuardada> anteriores=new HashMap<>();
  if(input.ventaGuardadaId()==null)venta=new VentaGuardada(p.tenantId(),ctx.empresa,siguienteNumero(p.tenantId(),ctx.empresa),ctx.caja.getSucursalId(),ctx.caja.getId(),ctx.terminal.getId(),ctx.almacen.getId(),p.usuarioId());
  else{venta=ventas.bloquear(input.ventaGuardadaId(),p.tenantId(),ctx.empresa).orElseThrow(()->new RecursoNoEncontradoException("Venta guardada no encontrada."));if(venta.getEstado()!=EstadoVentaGuardada.IN_USE||!p.usuarioId().equals(venta.getRecuperadaPor())||!ctx.terminal.getId().equals(venta.getTerminalRecuperacionId())||!venta.getSucursalId().equals(ctx.caja.getSucursalId()))throw new ReglaNegocioException("La venta ya está siendo utilizada en otra caja.");for(var l:lineas.findAllByVentaIdAndTenantIdAndEmpresaIdOrderByOrden(venta.getId(),p.tenantId(),ctx.empresa))anteriores.put(l.getProductoId(),l);}
  Cliente cliente=input.clienteId()==null?null:clientes.findByIdAndTenantIdAndEmpresaId(input.clienteId(),p.tenantId(),ctx.empresa).filter(Cliente::isActivo).orElseThrow(()->new RecursoNoEncontradoException("Cliente no encontrado."));Set<UUID> ids=new HashSet<>();List<Calculada> calculadas=new ArrayList<>();List<LineaVistaPreviaDescuentoInput> solicitudLineas=new ArrayList<>();int items=0;
  for(var entrada:input.lineas()){if(entrada==null||entrada.productoId()==null||entrada.cantidad()==null||entrada.cantidad().signum()<=0)throw new ReglaNegocioException("Todas las cantidades deben ser mayores que cero.");if(!ids.add(entrada.productoId()))throw new ReglaNegocioException("El producto ya existe en la venta.");Producto producto=productos.findByIdAndTenantIdAndEmpresaId(entrada.productoId(),p.tenantId(),ctx.empresa).filter(Producto::isActivo).orElseThrow(()->new RecursoNoEncontradoException("Producto no encontrado."));if(!ctx.caja.getMonedaId().equals(producto.getMonedaId()))throw new ReglaNegocioException("El producto "+producto.getNombre()+" utiliza una moneda distinta a la caja.");BigDecimal cantidad=scale(entrada.cantidad()),precio=scale(entrada.precio()),tasa=tax(entrada.tasaImpuesto());LineaVentaGuardada anterior=anteriores.get(producto.getId());BigDecimal precioPermitido=anterior==null?scale(producto.getPrecioVenta()):anterior.getPrecio();BigDecimal tasaPermitida=anterior==null?(producto.getImpuestoVenta()!=null&&producto.getImpuestoVenta().isActivo()?tax(producto.getImpuestoVenta().getPorcentaje()):zero()):anterior.getTasaImpuesto();if(precio.compareTo(precioPermitido)!=0||tasa.compareTo(tasaPermitida)!=0)throw new ReglaNegocioException("El precio o impuesto de "+producto.getNombre()+" cambió. Actualiza la venta antes de guardarla.");UUID lineaId=entrada.lineaId()==null?producto.getId():entrada.lineaId();calculadas.add(new Calculada(lineaId,producto,cantidad,precio,tasa,precio.multiply(cantidad).setScale(SCALE,RoundingMode.HALF_UP)));solicitudLineas.add(new LineaVistaPreviaDescuentoInput(lineaId,producto.getId(),producto.getNombre(),cantidad,precio,tasa,producto.isPermiteDescuentos()));items++;}
  VistaPreviaDescuentoDto vista=input.detalleDescuento()==null?sinDescuento(solicitudLineas):descuentos.previsualizar(new SolicitudVistaPreviaDescuentoInput(UUID.randomUUID(),sinAutorizacion(input.detalleDescuento()),solicitudLineas));Map<UUID,VistaPreviaDescuentoDto.Asignacion> asignaciones=new HashMap<>();vista.asignaciones().forEach(x->asignaciones.put(x.lineaId(),x));List<LineaVistaPreviaRecargoInput> solicitudRecargo=calculadas.stream().map(c->{var a=asignaciones.get(c.lineaId);return new LineaVistaPreviaRecargoInput(c.lineaId,c.producto.getId(),c.producto.getNombre(),c.cantidad,c.precio,c.tasa,a.descuento(),c.producto.isPermiteRecargos());}).toList();VistaPreviaRecargoDto vistaRecargo=input.detalleRecargo()==null?sinRecargo(solicitudRecargo):recargos.previsualizar(new SolicitudVistaPreviaRecargoInput(UUID.randomUUID(),sinAutorizacion(input.detalleRecargo()),solicitudRecargo));Map<UUID,VistaPreviaRecargoDto.Asignacion> asignacionesRecargo=new HashMap<>();vistaRecargo.asignaciones().forEach(x->asignacionesRecargo.put(x.lineaId(),x));BigDecimal subtotal=zero(),descuento=zero(),recargo=zero(),impuestos=zero(),total=zero();for(var c:calculadas){var a=asignaciones.get(c.lineaId);var r=asignacionesRecargo.get(c.lineaId);subtotal=subtotal.add(a.subtotalBruto());descuento=descuento.add(a.descuento());recargo=recargo.add(r.recargo());impuestos=impuestos.add(r.impuesto());total=total.add(r.total());}venta.actualizar(ctx.caja.getSucursalId(),ctx.caja.getId(),ctx.terminal.getId(),ctx.almacen.getId(),cliente==null?null:cliente.getId(),cliente==null?"Consumidor Final":nombre(cliente),cliente==null?null:cliente.getIdentificacion(),ctx.caja.getMonedaId(),ctx.caja.getMoneda().getCodigoIso(),texto(input.referencia(),150),texto(input.observacion(),1000),subtotal,descuento,recargo,impuestos,total,items,p.usuarioId());DescuentoVentaInput d=input.detalleDescuento();venta.descuento(d==null?null:d.alcance(),d==null?null:d.tipo(),d==null?null:d.valor(),null,d==null?null:d.motivoId(),vista.motivoNombre(),d==null?null:texto(d.detalle(),500),null);RecargoVentaInput sr=input.detalleRecargo();venta.recargo(sr==null?null:sr.alcance(),sr==null?null:sr.tipo(),sr==null?null:sr.valor(),sr==null?null:sr.conceptoId(),sr==null?null:sr.motivoId(),vistaRecargo.motivoNombre(),sr==null?null:texto(sr.detalle(),500),null);venta=ventas.saveAndFlush(venta);lineas.deleteAllByVentaIdAndTenantIdAndEmpresaId(venta.getId(),p.tenantId(),ctx.empresa);lineas.flush();int orden=1;for(var c:calculadas){var a=asignaciones.get(c.lineaId);var r=asignacionesRecargo.get(c.lineaId);lineas.save(new LineaVentaGuardada(venta,c.producto,c.producto.getUnidadMedida().getAbreviatura(),c.cantidad,c.precio,c.tasa,a.subtotalBruto(),a.descuento(),r.recargo(),r.baseImponible(),r.impuesto(),r.total(),orden++));}lineas.flush();auditoria.registrar(input.ventaGuardadaId()==null?"SAVED_SALE_CREATED":"SAVED_SALE_UPDATED","VentaGuardada",venta.getId(),"{\"numero\":\""+venta.getNumero()+"\",\"descuento\":"+descuento+",\"recargo\":"+recargo+",\"cajaId\":\""+ctx.caja.getId()+"\"}");return new VentaGuardadaResultadoDto(venta.getId(),venta.getNumero());}

 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('ventas_guardadas.consultar')")
 public Page<VentaGuardadaResumenDto> buscar(String token,String q,int page){if(page<0)throw new ReglaNegocioException("La página solicitada no es válida.");Contexto c=contexto(token,null);var p=c.principal;boolean otros=p.permisos().contains("ventas_guardadas.recuperar_otros");return ventas.buscar(p.tenantId(),c.empresa,c.caja.getSucursalId(),p.usuarioId(),c.terminal.getId(),otros,clean(q).toLowerCase(Locale.ROOT),PageRequest.of(page,10)).map(v->new VentaGuardadaResumenDto(v.getId(),v.getNumero(),v.getActualizadaEn(),v.getReferencia(),v.getClienteNombre(),v.getCantidadItems(),v.getTotal(),v.getMonedaCodigo()));}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('ventas_guardadas.consultar')")
 public long contar(String token){Contexto c=contexto(token,null);var p=c.principal;return ventas.contar(p.tenantId(),c.empresa,c.caja.getSucursalId(),p.usuarioId(),c.terminal.getId(),p.permisos().contains("ventas_guardadas.recuperar_otros"));}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('ventas_guardadas.recuperar')")
 public VentaGuardadaRecuperadaDto recuperar(UUID id,String token,UUID almacenId){Contexto c=contexto(token,almacenId);var p=c.principal;VentaGuardada v=ventas.bloquear(id,p.tenantId(),c.empresa).orElseThrow(()->new RecursoNoEncontradoException("Venta guardada no encontrada."));autorizar(v,c);boolean yaControladaAqui=v.getEstado()==EstadoVentaGuardada.IN_USE&&p.usuarioId().equals(v.getRecuperadaPor())&&c.terminal.getId().equals(v.getTerminalRecuperacionId());if(v.getEstado()!=EstadoVentaGuardada.SAVED&&!yaControladaAqui)throw new ReglaNegocioException("La venta ya está siendo utilizada en otra caja.");if(!v.getMonedaId().equals(c.caja.getMonedaId()))throw new ReglaNegocioException("La moneda de la venta ya no coincide con la moneda de la caja.");ClientePosDto cliente=null;if(v.getClienteId()!=null){Cliente x=clientes.findByIdAndTenantIdAndEmpresaId(v.getClienteId(),p.tenantId(),c.empresa).filter(Cliente::isActivo).orElseThrow(()->new ReglaNegocioException("El cliente de la venta ya no está disponible."));cliente=new ClientePosDto(x.getId(),x.getCodigo(),nombre(x),x.getTipoIdentificacion(),x.getIdentificacion(),x.getTelefono());}
  List<VentaGuardadaRecuperadaDto.Producto> salida=new ArrayList<>();List<LineaVistaPreviaDescuentoInput> solicitudLineas=new ArrayList<>();List<LineaVistaPreviaRecargoInput> solicitudRecargo=new ArrayList<>();List<UUID> seleccionadas=new ArrayList<>(),seleccionadasRecargo=new ArrayList<>();for(var l:lineas.findAllByVentaIdAndTenantIdAndEmpresaIdOrderByOrden(v.getId(),p.tenantId(),c.empresa)){Producto producto=productos.findByIdAndTenantIdAndEmpresaId(l.getProductoId(),p.tenantId(),c.empresa).filter(Producto::isActivo).orElseThrow(()->new ReglaNegocioException("El producto "+l.getNombre()+" ya no está disponible."));if(!producto.getMonedaId().equals(c.caja.getMonedaId()))throw new ReglaNegocioException("El producto "+l.getNombre()+" utiliza una moneda distinta a la caja.");BigDecimal disponible=producto.isControlaExistencia()?existencias.saldo(p.tenantId(),c.empresa,c.almacen.getId(),producto.getId()):zero();if(producto.isControlaExistencia()&&!producto.isPermiteExistenciaNegativa()&&disponible.compareTo(l.getCantidad())<0)throw new ReglaNegocioException("Existencia insuficiente para "+producto.getNombre()+". La venta permanece guardada.");salida.add(new VentaGuardadaRecuperadaDto.Producto(l.getId(),producto.getId(),l.getCodigo(),l.getNombre(),l.getUnidad(),l.getPrecio(),l.getTasaImpuesto(),disponible,producto.isControlaExistencia(),producto.isPermiteExistenciaNegativa(),producto.isPermiteDescuentos(),producto.isPermiteRecargos(),l.getCantidad()));solicitudLineas.add(new LineaVistaPreviaDescuentoInput(l.getId(),producto.getId(),l.getNombre(),l.getCantidad(),l.getPrecio(),l.getTasaImpuesto(),producto.isPermiteDescuentos()));solicitudRecargo.add(new LineaVistaPreviaRecargoInput(l.getId(),producto.getId(),l.getNombre(),l.getCantidad(),l.getPrecio(),l.getTasaImpuesto(),l.getDescuento(),producto.isPermiteRecargos()));if(l.getDescuento()!=null&&l.getDescuento().signum()>0)seleccionadas.add(l.getId());if(l.getRecargo()!=null&&l.getRecargo().signum()>0)seleccionadasRecargo.add(l.getId());}
  if(salida.isEmpty())throw new ReglaNegocioException("La venta guardada no contiene productos.");DescuentoVentaInput detalle=v.getAlcanceDescuento()==null?null:new DescuentoVentaInput(v.getAlcanceDescuento(),v.getTipoDescuento(),v.getValorDescuento(),v.getAlcanceDescuento()==AlcanceDescuentoVenta.LINE?seleccionadas:List.of(),v.getMotivoDescuentoId(),v.getMotivoDescuentoDetalle(),null);if(detalle!=null)descuentos.previsualizar(new SolicitudVistaPreviaDescuentoInput(UUID.randomUUID(),detalle,solicitudLineas));RecargoVentaInput detalleRecargo=v.getAlcanceRecargo()==null?null:new RecargoVentaInput(v.getAlcanceRecargo(),v.getTipoRecargo(),v.getValorRecargo(),v.getAlcanceRecargo()==AlcanceRecargoVenta.LINE?seleccionadasRecargo:List.of(),v.getConceptoRecargoId(),v.getMotivoRecargoId(),v.getMotivoRecargoDetalle(),null);if(detalleRecargo!=null)recargos.previsualizar(new SolicitudVistaPreviaRecargoInput(UUID.randomUUID(),detalleRecargo,solicitudRecargo));if(!yaControladaAqui){v.recuperar(p.usuarioId(),c.terminal.getId());ventas.saveAndFlush(v);auditoria.registrar("SAVED_SALE_RECOVERED","VentaGuardada",v.getId(),"{\"numero\":\""+v.getNumero()+"\",\"cajaId\":\""+c.caja.getId()+"\"}");}return new VentaGuardadaRecuperadaDto(v.getId(),v.getNumero(),v.getReferencia(),v.getObservacion(),cliente,v.getMonedaCodigo(),v.getDescuento(),v.getRecargo(),detalle,detalleRecargo,salida);}

 @Transactional @PreAuthorize("@empresaModuloService.habilitado('VENTAS') and hasAuthority('ventas_guardadas.descartar')")
 public void descartar(UUID id,String token){Contexto c=contexto(token,null);var p=c.principal;VentaGuardada v=ventas.bloquear(id,p.tenantId(),c.empresa).orElseThrow(()->new RecursoNoEncontradoException("Venta guardada no encontrada."));autorizar(v,c);if(v.getEstado()!=EstadoVentaGuardada.SAVED)throw new ReglaNegocioException("La venta ya está siendo utilizada y no puede descartarse.");v.descartar(p.usuarioId());ventas.saveAndFlush(v);auditoria.registrar("SAVED_SALE_DISCARDED","VentaGuardada",v.getId(),"{\"numero\":\""+v.getNumero()+"\"}");}

 @Transactional public void completarDesdeFactura(UUID id,UUID facturaId,UUID usuario,UUID terminal,UUID tenant,UUID empresa){if(id==null)return;VentaGuardada v=ventas.bloquear(id,tenant,empresa).orElseThrow(()->new RecursoNoEncontradoException("Venta guardada no encontrada."));if(v.getEstado()!=EstadoVentaGuardada.IN_USE||!usuario.equals(v.getRecuperadaPor())||!terminal.equals(v.getTerminalRecuperacionId()))throw new ReglaNegocioException("La venta guardada ya no está disponible para facturarse.");v.completar(facturaId,usuario);ventas.saveAndFlush(v);auditoria.registrar("SAVED_SALE_COMPLETED","VentaGuardada",v.getId(),"{\"numero\":\""+v.getNumero()+"\",\"facturaId\":\""+facturaId+"\"}");}

 private void autorizar(VentaGuardada v,Contexto c){var p=c.principal;if(!v.getSucursalId().equals(c.caja.getSucursalId())||!EmpresaContext.permiteSucursal(v.getSucursalId()))throw new RecursoNoEncontradoException("Venta guardada no encontrada.");if(!v.getCreadaPor().equals(p.usuarioId())&&!p.permisos().contains("ventas_guardadas.recuperar_otros"))throw new RecursoNoEncontradoException("Venta guardada no encontrada.");}
 private Contexto contexto(String token,UUID almacenEsperado){if(token==null||token.isBlank())throw new ReglaNegocioException("Esta terminal no está configurada.");var p=TenantContext.principalActual();UUID empresa=p.empresaId();TerminalPos terminal=terminales.findByTokenHashAndTenantIdAndEmpresaIdAndActivoTrue(hash(token),p.tenantId(),empresa).orElseThrow(()->new ReglaNegocioException("Esta terminal no está configurada o fue desactivada."));if(!EmpresaContext.permiteSucursal(terminal.getSucursalId()))throw new RecursoNoEncontradoException("Terminal no encontrada.");Caja caja=cajas.findByIdAndTenantIdAndEmpresaId(terminal.getCajaId(),p.tenantId(),empresa).filter(Caja::isActivo).orElseThrow(()->new ReglaNegocioException("La caja configurada ya no está disponible."));Sucursal sucursal=sucursales.findByIdAndEmpresaId(caja.getSucursalId(),empresa).orElseThrow(()->new ReglaNegocioException("La sucursal configurada ya no está disponible."));Almacen almacen=almacenes.resolver(p.tenantId(),empresa,sucursal);if(almacenEsperado!=null&&!almacenEsperado.equals(almacen.getId()))throw new ReglaNegocioException("La configuración del almacén cambió. Reinicia la venta antes de continuar.");return new Contexto(p,empresa,terminal,caja,almacen);}
 private String siguienteNumero(UUID tenant,UUID empresa){Long n=jdbc.queryForObject("INSERT INTO saved_sale_sequence(tenant_id,empresa_id,last_number) VALUES(?,?,1) ON CONFLICT(tenant_id,empresa_id) DO UPDATE SET last_number=saved_sale_sequence.last_number+1 RETURNING last_number",Long.class,tenant,empresa);return "VGU-"+String.format(Locale.ROOT,"%06d",n);}
 private static VistaPreviaDescuentoDto sinDescuento(List<LineaVistaPreviaDescuentoInput> lineas){List<VistaPreviaDescuentoDto.Asignacion> a=lineas.stream().map(x->{BigDecimal bruto=scale(x.precioEsperado()).multiply(scale(x.cantidad())).setScale(SCALE,RoundingMode.HALF_UP);BigDecimal impuesto=bruto.multiply(x.tasaImpuestoEsperada()==null?BigDecimal.ZERO:x.tasaImpuestoEsperada()).divide(new BigDecimal("100"),SCALE,RoundingMode.HALF_UP);return new VistaPreviaDescuentoDto.Asignacion(x.lineaId(),x.productoId(),bruto,zero(),bruto,impuesto,bruto.add(impuesto));}).toList();return new VistaPreviaDescuentoDto(zero(),zero(),zero(),zero(),false,null,null,null,false,a);}
 private static VistaPreviaRecargoDto sinRecargo(List<LineaVistaPreviaRecargoInput> lineas){List<VistaPreviaRecargoDto.Asignacion>a=lineas.stream().map(x->{BigDecimal base=scale(x.precioEsperado()).multiply(scale(x.cantidad())).subtract(scale(x.descuentoAplicado())).setScale(SCALE,RoundingMode.HALF_UP);BigDecimal impuesto=base.multiply(x.tasaImpuestoEsperada()==null?BigDecimal.ZERO:x.tasaImpuestoEsperada()).divide(new BigDecimal("100"),SCALE,RoundingMode.HALF_UP);return new VistaPreviaRecargoDto.Asignacion(x.lineaId(),x.productoId(),base,zero(),base,impuesto,base.add(impuesto));}).toList();return new VistaPreviaRecargoDto(zero(),zero(),zero(),zero(),false,null,null,null,null,false,a);}
 private static DescuentoVentaInput sinAutorizacion(DescuentoVentaInput d){return new DescuentoVentaInput(d.alcance(),d.tipo(),d.valor(),d.lineaIds(),d.motivoId(),d.detalle(),null);}
 private static RecargoVentaInput sinAutorizacion(RecargoVentaInput d){return new RecargoVentaInput(d.alcance(),d.tipo(),d.valor(),d.lineaIds(),d.conceptoId(),d.motivoId(),d.detalle(),null);}
 private static String texto(String v,int max){String s=clean(v);if(s.length()>max)throw new ReglaNegocioException("El dato ingresado excede el máximo permitido.");return s.isEmpty()?null:s;}private static String clean(String v){return v==null?"":v.trim();}private static BigDecimal scale(BigDecimal v){return(v==null?BigDecimal.ZERO:v).setScale(SCALE,RoundingMode.HALF_UP);}private static BigDecimal tax(BigDecimal v){return(v==null?BigDecimal.ZERO:v).setScale(6,RoundingMode.HALF_UP);}private static BigDecimal zero(){return BigDecimal.ZERO.setScale(SCALE);}private static BigDecimal nonNegative(BigDecimal v,String m){BigDecimal x=scale(v);if(x.signum()<0)throw new ReglaNegocioException(m);return x;}private static String nombre(Cliente c){return c.getTipoPersona()==TipoPersonaCliente.JURIDICA?c.getRazonSocial():(clean(c.getNombres())+" "+clean(c.getApellidos())).trim();}private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private record Contexto(com.citacloud.springboot.contacloud.app.security.TenantPrincipal principal,UUID empresa,TerminalPos terminal,Caja caja,Almacen almacen){}private record Calculada(UUID lineaId,Producto producto,BigDecimal cantidad,BigDecimal precio,BigDecimal tasa,BigDecimal subtotal){}
}
